#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# 時刻の形式が違うときは exit 2 で、stderr に規約の文言を出す（cli-conventions.md）
expect_bad_time() {
  err=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 "$1" "$2" x 2>&1 >/dev/null); rc=$?
  [ "$rc" = 2 ] || { echo "bad time $1 $2: exit $rc, expected 2"; fail=1; }
  [ "$err" = "bad time: $3 (expected HH:MM)" ] || { echo "bad time $1 $2: stderr was '$err'"; fail=1; }
}
expect_bad_time 9am 10:00 9am
expect_bad_time 10:00 1100 1100
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail

