BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10am x >/dev/null 2>&1; [ $? = 2 ] || { echo "10am end should exit 2"; fail=1; }
[ "$(grep -vc '^#' "$t")" = 0 ] || { echo "a rejected booking was stored"; fail=1; }
rm -f "$t"; exit $fail
EOF
echo "--- before fix (expect failure)"; bash spec/book_time.spec.sh; echo "rc=$?"
sed -i '7s/echo "bad time: \$x (expected HH:MM)" >&2; exit 1; }/echo "bad time: $x (expected HH:MM)" >\&2; exit 2; }/' src/book.sh
sed -n 7p src/book.sh
echo "--- after fix"; bash spec/book_time.spec.sh; echo "rc=$?"

